function csvImportPlan(){
 if(!csvImportPending)return {records:[],errors:[],duplicates:[],preview:[]};
 const {headers,rows,mapping}=csvImportPending,records=[],errors=[],duplicates=[],preview=[],existing=new Set(state.records.map(r=>csvKey(r.name))),seen=new Set();
 const duplicateMode=$('#csvDuplicateMode')?.value||'skip';
 rows.forEach((row,index)=>{const rowNo=index+2;try{
  const get=k=>mapping[k]?row[mapping[k]]:'';
  const name=String(get('name')||'').trim();if(!name)throw Error(`Row ${rowNo}: map a column with the product or activity name.`);
  const activityType=importedActivityType(get('activityType'),rowNo),saleUnit=String(get('saleUnit')||'').trim()||ToolkitTemplateFor(activityType).unit;
  const yieldCount=csvNumber(get('yield'),'batch yield',rowNo,1),price=csvNumber(get('price'),'selling price',rowNo,0),materialCost=csvNumber(get('materialCost'),'materials total',rowNo,0),packagingCost=csvNumber(get('packagingCost'),'packaging total',rowNo,0),hours=csvNumber(get('hours'),'labor hours',rowNo,0),rate=csvNumber(get('rate'),'hourly rate',rowNo,0),other=csvNumber(get('other'),'other batch costs',rowNo,0),wastePercent=csvNumber(get('wastePercent'),'waste percent',rowNo,0),overhead=csvNumber(get('overhead'),'overhead per unit',rowNo,0);
  if(yieldCount<=0)throw Error(`Row ${rowNo}: batch yield must be greater than zero.`);
  if([price,materialCost,packagingCost,hours,rate,other,overhead].some(v=>v<0))throw Error(`Row ${rowNo}: prices, costs, hours, rates, and overhead must be nonnegative.`);
  if(wastePercent<0||wastePercent>=100)throw Error(`Row ${rowNo}: waste must be from 0% to less than 100%.`);
  if(!(materialCost>0||packagingCost>0||hours*rate>0||other>0||overhead>0))throw Error(`Row ${rowNo}: add at least one positive cost so the saved activity can be calculated.`);
  const key=csvKey(name);if(duplicateMode==='skip'&&(existing.has(key)||seen.has(key))){duplicates.push({rowNo,name});preview.push({rowNo,name,status:'Skipped: same name already exists'});return}
  seen.add(key);
  const materials=materialCost>0?[{name:'Imported materials subtotal',buyQty:1,buyUnit:'unit',paid:materialCost,used:1,useUnit:'unit'}]:[];
  const packaging=packagingCost>0?[{name:'Imported packaging subtotal',buyQty:1,buyUnit:'unit',paid:packagingCost,used:1,useUnit:'unit'}]:[];
  records.push({id:uid(),name,yield:yieldCount,price,hours,rate,other,materials,packaging,activityType,saleUnit,customCosts:[],wastePercent,overhead});
  preview.push({rowNo,name,status:'Ready to add'});
 }catch(e){errors.push({rowNo,message:e.message});preview.push({rowNo,name:String(row[mapping.name]||'').trim()||'â€”',status:e.message})}});
 return {records,errors,duplicates,preview};
}
function renderCsvImport(){const box=$('#csvImportMappings');if(!box||!csvImportPending)return;
 const h=csvImportPending.headers;box.innerHTML=`<h3>Match spreadsheet columns</h3><p>Select the column that holds each kind of information. One spreadsheet row becomes one saved activity.</p><div class="grid">${csvMapFields.map(([key,label,aliases])=>csvColumnSelect(key,label,aliases,h)).join('')}</div><label>If a saved activity has the same name<select id="csvDuplicateMode"><option value="skip">Skip it (recommended)</option><option value="keep">Import as a separate record</option></select></label>`;
 box.querySelectorAll('[data-csv-map]').forEach(el=>el.addEventListener('change',()=>{csvImportPending.mapping[el.dataset.csvMap]=el.value;updateCsvImportPreview()}));$('#csvDuplicateMode').addEventListener('change',updateCsvImportPreview);
 updateCsvImportPreview();
}
function updateCsvImportPreview(){const box=$('#csvImportPreview');if(!box||!csvImportPending)return;const plan=csvImportPlan(),shown=plan.preview.slice(0,8);box.innerHTML=`<p><strong>${plan.records.length}</strong> row(s) ready to add; ${plan.duplicates.length} same-name row(s) skipped; ${plan.errors.length} row(s) need correction${plan.preview.length>shown.length?` (showing ${shown.length} of ${plan.preview.length})`:''}.</p>${shown.length?`<div class="table-wrap"><table><thead><tr><th>CSV row</th><th>Activity</th><th>Result</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${r.rowNo}</td><td>${esc(r.name)}</td><td>${esc(r.status)}</td></tr>`).join('')}</tbody></table></div>`:''}<button type="button" class="primary" id="csvImportApply" ${plan.records.length?'':'disabled'}>Add ${plan.records.length} Saved Activit${plan.records.length===1?'y':'ies'}</button>`;
 $('#csvImportApply')?.addEventListener('click',()=>{const latest=csvImportPlan();if(!latest.records.length)return message('#csvImportStatus','No valid new activities are ready to import.','error');const ok=confirm(`Add ${latest.records.length} saved activit${latest.records.length===1?'y':'ies'}? Existing Toolkit records will be kept. Imported money amounts use the current My Business currency (${state.profile.currency}); no currency conversion is performed.`);if(!ok)return;const previous=state.records;state.records=[...state.records,...latest.records];if(!save()){state.records=previous;return message('#csvImportStatus',storageError,'error')}const skipped=latest.duplicates.length+latest.errors.length;csvImportPending=null;render();message('#csvImportStatus',`Added ${latest.records.length} saved activit${latest.records.length===1?'y':'ies'}. Existing data was kept.${skipped?` ${skipped} row(s) were skipped; see the preview and correct them if needed.`:''}`)});
}
function settings(){return `<section class="card"><h2>Appearance</h2><label>Accent color<input type="color" id="theme" value="${esc(state.theme)}"></label><button class="primary" id="saveTheme">Apply Theme</button><div id="themeStatus"></div></section><section class="card"><h2>Import spreadsheet data</h2><p>Save an Excel or Google Sheets worksheet as CSV (UTF-8), then upload it. One row should represent one product, service, recipe, job, or other activity. Map its columns and review the rows before importing. Your file is read on this device; it is not uploaded to a server.</p><p class="muted">Existing records are kept. Same-name activities are skipped by default. Material, packaging, and other cost columns import as batch totals, not detailed line items. Imported amounts must use the currency already selected in My Business; no conversion is performed. Direct .xlsx upload is not supported yet.</p><div class="row"><label>Choose CSV file<input type="file" id="csvImportFile" accept=".csv,text/csv"></label><button type="button" class="secondary" id="csvTemplate">Download CSV template</button></div><div id="csvImportMappings"></div><div id="csvImportPreview"></div><div id="csvImportStatus"></div></section><section class="card"><h2>Data Management</h2><p>Saved data stays in this browser on this device. Download backups regularly. Private browsing or cleared site data can erase local records.</p><div class="row"><button class="primary" id="backup">Download Backup</button><label>Restore JSON backup<input type="file" id="restore" accept=".json,application/json"></label><button class="secondary" id="reset">Delete Saved Data</button></div><div id="settingsStatus"></div><div class="row"><button class="secondary" id="storageCheck">Check Local Database</button><button class="secondary" id="recoverDB">Recover Local Database</button></div><p class="muted">Recovery will ask before replacing current data. Keep a downloaded backup on a separate device.</p></section><section class="card"><h2>Take your business numbers with you</h2><p>When you're ready for more detailed financial management, FyscalOSâ„¢ is the next step. Your toolkit works independentlyâ€”you do not need FyscalOSâ„¢ to use it.</p><p>Download a structured copy of your business setup, saved activities, prices, offers, plans, and contacts. This file is for future transfer; it does not connect to or import into FyscalOSâ„¢ today.</p><button class="secondary" id="portableExport">Download My Business Data</button><div id="exportStatus"></div><label>Import Toolkit transfer file<input type="file" id="transferImport" accept=".json,application/json"></label><p class="muted">Keep this file private. It may contain commercially sensitive information. No data is sent to a server by this button.</p></section>`}
function history(items,describe){return items.length?items.slice().reverse().map(x=>`<div class="saved-item"><span>${esc(describe(x))}</span><small>${esc(x.date||'')}</small></div>`).join(''):'<p>No saved decisions yet.</p>'}
function health(){return `<section class="card"><h2>Business Health & Sales Targets</h2><p>Use your saved cost estimates to explore how many sales you may need. This is a planning estimate, not a record of actual business income.</p><label>Choose saved activity<select id="selected">${recordOptions()}</select></label><label>Monthly fixed expenses<input id="healthFixed" type="number" min="0" step="any" value="${esc(state.monthlyFixedCosts||0)}"></label><label>Extra earnings goal per month<input id="healthGoal" type="number" min="0" step="any" value="${esc(state.monthlyGoal||0)}"></label><label>Expected sales you can complete each month<input id="healthCapacity" type="number" min="1" step="1" value="40"></label><button class="primary" id="runHealth">Check My Business Numbers</button><div id="healthOutput" aria-live="polite"></div></section>`}
const views={Home:home,'My Business':business,Cost:cost,Price:price,Sell:sell,Plan:plan,Contacts:contacts,Reports:reports,'Business Health':health,Help:help,Settings:settings};
