$('#runPlan')?.addEventListener('click',()=>{try{const r=requireProduct(),cc=number($('#costChange').value),pc=number($('#priceChange').value),volume=number($('#volume').value),c=calculate(r);if(!Number.isFinite(cc)||cc< -100||!Number.isFinite(pc)||pc< -100||!Number.isInteger(volume)||volume<1)throw Error('Enter valid percentage changes and a whole-number quantity of at least 1.');const nextCost=c.unit*(1+cc/100),nextPrice=n(r.price)*(1+pc/100),current=(n(r.price)-c.unit)*volume,next=(nextPrice-nextCost)*volume,difference=next-current;showResult(`<div class="table-wrap"><table><tr><th></th><th>Current</th><th>Scenario</th><th>Difference</th></tr><tr><td>Unit cost</td><td>${fmt(c.unit)}</td><td>${fmt(nextCost)}</td><td>${fmt(nextCost-c.unit)}</td></tr><tr><td>Unit price</td><td>${fmt(r.price)}</td><td>${fmt(nextPrice)}</td><td>${fmt(nextPrice-n(r.price))}</td></tr><tr><td>Amount remaining Ã— ${volume}</td><td>${fmt(current)}</td><td>${fmt(next)}</td><td>${fmt(difference)}</td></tr></table></div>${alert('Scenario only. Your original product is unchanged.')}<button class="primary" id="saveDecision">Save Scenario</button><div id="decisionStatus"></div>`);saveDecisionButton('scenarios',{recordId:r.id,productName:r.name,costChange:cc,priceChange:pc,volume,current,next,difference})}catch(e){showResult(alert(e.message,'error'))}});
