$('#saveTheme')?.addEventListener('click',()=>{const prev=state.theme;state.theme=$('#theme').value;if(!save()){state.theme=prev;message('#themeStatus',storageError,'error')}else{document.documentElement.style.setProperty('--accent',state.theme);message('#themeStatus','Theme saved.')}});
$('#portableExport')?.addEventListener('click',()=>{try{downloadJson(portableExport(),'business-numbers-toolkit-transfer-v1.json');message('#exportStatus','Transfer file prepared. Keep it somewhere safe.')}catch(e){message('#exportStatus','Could not create the transfer file: '+e.message,'error')}});
$('#csvTemplate')?.addEventListener('click',csvTemplate);
$('#csvImportFile')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('CSV file is larger than 5 MB. Split it into smaller files and import them separately.');const parsed=ToolkitCSV.parse(await file.text());const headers=parsed.headers,normalized=headers.map(csvKey),mapping={};for(const [key,,aliases] of csvMapFields){const match=aliases.map(csvKey).find(a=>normalized.includes(a));mapping[key]=match?headers[normalized.indexOf(match)]:''}csvImportPending={fileName:file.name,headers,rows:parsed.rows,mapping};renderCsvImport();message('#csvImportStatus',`Loaded ${parsed.rows.length} data rows from ${file.name}. Review the column matches and preview before importing.`)}catch(err){csvImportPending=null;$('#csvImportMappings').replaceChildren();$('#csvImportPreview').replaceChildren();message('#csvImportStatus',err.message,'error')}});
$('#transferImport')?.addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>15000000)throw Error('Transfer file is too large.');const data=JSON.parse(await f.text());const imported=ToolkitTransfer.parse(data);if(!confirm('Import this transfer file and replace the current Toolkit records? Download a backup first.'))return;const previous=state;state=normalize(imported);if(!save()){state=previous;throw Error(storageError)}render()}catch(err){message('#exportStatus','Import failed: '+err.message,'error')}});
$('#storageCheck')?.addEventListener('click',async()=>{try{const info=await ToolkitStorage.inspect();message('#settingsStatus',info?'Local database backup found, dated '+info.savedAt+'.':'No local database backup found.','warning')}catch(err){message('#settingsStatus','Database unavailable: '+err.message,'error')}});
$('#recoverDB')?.addEventListener('click',async()=>{try{const backup=await ToolkitStorage.inspect();if(!backup)throw Error('No recovery snapshot found.');if(!confirm('Replace current data with the local database snapshot from '+backup.savedAt+'? Download a backup first.'))return;const prev=state;state=normalize(backup.data);if(!save()){state=prev;throw Error(storageError)}render()}catch(err){message('#settingsStatus','Recovery failed: '+err.message,'error')}});

$('#backup')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='business-numbers-toolkit-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)});
$('#restore')?.addEventListener('change',async e=>{try{const file=e.target.files?.[0];if(!file)return;const incoming=JSON.parse(await file.text());if(!incoming.profile||!Array.isArray(incoming.records))throw Error('Invalid toolkit backup.');if(!confirm('Replace all current toolkit data with this backup?'))return;const prev=state;state=normalize(incoming);if(!save()){state=prev;throw Error(storageError)}render()}catch(err){message('#settingsStatus','Restore failed: '+err.message,'error')}});
$('#reset')?.addEventListener('click',()=>{if(!confirm('Delete all toolkit data on this device? Download a backup first.'))return;const prev=state;state=empty();if(!save()){state=prev;message('#settingsStatus',storageError,'error')}else render()});
